INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19899$nota-0171$m19899$, $m19900$Manual treinamento.pdf$m19900$, $m19901$82$m19901$, $m19902$O LT1 corresponde ao primeiro aumento consistente da concentração de lactato acima dos valores de repouso... Características típicas do LT1: predominância do metabolismo oxidativo; elevada contribuição da oxidação de gorduras; baixa perturbação da homeostase; ventilação ainda proporcional ao consumo de oxigênio; possibilidade de sustentação por várias horas.$m19902$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m19903$nota-0171$m19903$, $m19904$nota-0145$m19904$, $m19905$complementa$m19905$, $m19906$detalha, com o modelo moderno de dois limiares (LT1/LT2), a distinção que a nota-0145 do Livro 1 já fazia entre 'limiar de lactato' (intensidade baixa) e MLSS/FTP (intensidade mais alta)$m19906$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19907$nota-0172$m19907$, $m19908$Manual treinamento.pdf$m19908$, $m19909$83$m19909$, $m19910$chega um momento em que a concentração de lactato passa a crescer de forma muito mais rápida. Esse ponto é conhecido como LT2. Nessa região: a glicólise acelera significativamente; aumenta a participação dos carboidratos; a ventilação cresce de maneira desproporcional; o equilíbrio ácido-base torna-se progressivamente mais instável. Acima dessa intensidade, o tempo de sustentação reduz-se consideravelmente.$m19910$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m19911$nota-0172$m19911$, $m19912$nota-0171$m19912$, $m19913$complementa$m19913$, $m19914$LT1 e LT2 formam o par de limiares que delimita os domínios de intensidade fisiológica (ver nota-0178)$m19914$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19915$nota-0173$m19915$, $m19916$Manual treinamento.pdf$m19916$, $m19917$84$m19917$, $m19918$'4 mmol/L representa o limiar anaeróbio para todos os atletas.' Evidência científica: Não. O valor de 4 mmol/L surgiu como uma referência prática (OBLA – Onset of Blood Lactate Accumulation), mas não representa um ponto fisiológico universal... As concentrações absolutas variam amplamente entre indivíduos... métodos modernos priorizam a análise individual das curvas de lactato.$m19918$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m19919$nota-0173$m19919$, $m19920$nota-0145$m19920$, $m19921$complementa$m19921$, $m19922$reforça e detalha, com evidência explícita 'mito ou verdade', a mesma advertência de desambiguação de OBLA já registrada na nota-0145 do Livro 1$m19922$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19923$nota-0174$m19923$, $m19924$Manual treinamento.pdf$m19924$, $m19925$84$m19925$, $m19926$O Maximum Lactate Steady State (MLSS) representa a maior intensidade na qual a concentração de lactato permanece relativamente estável durante exercício contínuo... é frequentemente considerado um dos melhores indicadores laboratoriais da máxima intensidade sustentável. Entretanto, sua determinação exige diversos testes realizados em dias diferentes. Por essa razão, seu uso na prática cotidiana é limitado.$m19926$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m19927$nota-0174$m19927$, $m19928$nota-0145$m19928$, $m19929$complementa$m19929$, $m19930$confirma e detalha a equivalência aproximada MLSS ≈ FTP já registrada na nota-0145 do Livro 1$m19930$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m19931$nota-0174$m19931$, $m19932$nota-0176$m19932$, $m19933$pre-requisito$m19933$, $m19934$a nota-0176 (FTP ≈ MLSS mas não é a mesma coisa) depende da definição precisa de MLSS estabelecida aqui$m19934$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19935$nota-0175$m19935$, $m19936$Manual treinamento.pdf$m19936$, $m19937$85$m19937$, $m19938$VT1 Corresponde aproximadamente ao primeiro limiar metabólico. Caracteriza-se pelo aumento da ventilação sem aumento proporcional da produção de dióxido de carbono. VT2 Representa intensidades próximas ao segundo limiar metabólico... hiperventilação significativa em resposta ao aumento da acidose metabólica. Esses limiares apresentam excelente correlação com LT1 e LT2.$m19938$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m19939$nota-0175$m19939$, $m19940$nota-0171$m19940$, $m19941$complementa$m19941$, $m19942$VT1 é o correlato ventilatório do LT1 (nota-0171)$m19942$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m19943$nota-0175$m19943$, $m19944$nota-0172$m19944$, $m19945$complementa$m19945$, $m19946$VT2 é o correlato ventilatório do LT2 (nota-0172)$m19946$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19947$nota-0023$m19947$, $m19948$Training and Racing with a Power Meter.pdf$m19948$, $m19949$61$m19949$, $m19950$TABLE 3.2 Expected Physiological and Performance Adaptations for Levels 1–7... Note: The plus signs represent the magnitude of adaptation for a given \"dose\" of training. The more plus signs, the greater the adaptation.$m19950$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m19951$nota-0023$m19951$, $m19952$nota-0022$m19952$, $m19953$pre-requisito$m19953$, $m19954$usa a mesma definição de níveis 1-7 da Tabela 3.1 (nota-0022)$m19954$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19955$nota-0047$m19955$, $m19956$Training and Racing with a Power Meter.pdf$m19956$, $m19957$109$m19957$, $m19958$all the training levels are continuous: There is no definitive starting or stopping point for any of them... The physiological systems in the human body that you are training meld into one another; if you are training in Level 3, you are using a larger percentage of that particular system than you are using for other systems at that intensity, but that does not mean the other systems are unaffected.$m19958$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m19959$nota-0047$m19959$, $m19960$nota-0022$m19960$, $m19961$complementa$m19961$, $m19962$lembra que os cortes numéricos da Tabela 3.1 (nota-0022) são simplificações práticas de um contínuo fisiológico real$m19962$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19963$nota-0088$m19963$, $m19964$Training and Racing with a Power Meter.pdf$m19964$, $m19965$228$m19965$, $m19966$the 'optimal' training load seems to lie at a CTL between 100 and 150 TSS per day... few, if any, athletes seem to be able to sustain a long-term average of more than 150 TSS per day.$m19966$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m19967$nota-0088$m19967$, $m19968$Training and Racing with a Power Meter.pdf$m19968$, $m19969$229$m19969$, $m19970$the hardest stages of such races [Tour de France] typically generate a TSS of 200-300... the highest continual CTL loads we have seen have been in riders at the Tour de France who can maintain a CTL between 150 and 160 for most of the year. After the Tour, they have a CTL of 170 to 180... a hypothetical genetic limit on CTL could be somewhere between 180 and 200.$m19970$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m19971$nota-0088$m19971$, $m19972$nota-0083$m19972$, $m19973$pre-requisito$m19973$, $m19974$usa o CTL definido na nota-0083$m19974$)
